for pid, terrain, continent, impass in cursor.fetchall():
    x = pid % WIDTH
    y = pid // WIDTH
    plots[(x, y)] = {
        'terrain': terrain,
        'continent': continent,
        'impassable': bool(impass),
        'id': pid,
        'feature': None
    }

cursor.execute('SELECT ID, FeatureType FROM PlotFeatures')
for pid, feature in cursor.fetchall():
    x = pid % WIDTH
    y = pid // WIDTH
    if (x, y) in plots:
        plots[(x, y)]['feature'] = feature

cursor.execute('SELECT * FROM PlotRivers')
river_data = {}
for r in cursor.fetchall():
    pid = r[0]
    x = pid % WIDTH
    y = pid // WIDTH
    river_data[(x, y)] = {
        'IsNEOfRiver': bool(r[1]),
        'IsWOfRiver': bool(r[2]),
        'IsNWOfRiver': bool(r[3]),
    }
