# y=14 is even. Offsets: (1,0),(-1,0),(0,1),(-1,1),(0,-1),(-1,-1)
# (22,14), (20,14), (21,15), (20,15), (21,13), (20,13)
# (21,15) = mountain -> +1
# (20,15) = jungle -> counts toward jungle
# (21,13) = geothermal fissure -> +1
# (20,13) = jungle -> counts toward jungle  
# So: 1 mountain + 1 geothermal + 2 jungles (= +1) = +3? Let me recheck.

# Wait, (22,11) is also a mountain. Let me recheck neighbors.
print("\n=== Double checking (21,14) neighbor calculation ===")
print(f"y=14, even row. Offsets: (1,0),(-1,0),(0,1),(-1,1),(0,-1),(-1,-1)")
print(f"Neighbors: ({21+1},{14}), ({21-1},{14}), ({21},{14+1}), ({21-1},{14+1}), ({21},{14-1}), ({21-1},{14-1})")

# Hmm, (20,14) doesn't exist as a land tile. Let me check
print(f"\n(20,14) exists in plots: {(20,14) in plots}")
print(f"(20,14) terrain: {plots.get((20,14), {}).get('terrain', 'N/A')}")

# So campus at (21,14):
# Mountains adj: (21,15) -> +1
# Geothermal: (21,13) -> +1
# Jungle: (20,15) and (20,13) -> 2 jungles -> +1
# Total base: 3

# Wait, earlier computation said 4. Let me recheck.
adj = 0
for nx, ny in get_neighbors(21, 14):
    p = plots.get((nx, ny), {})
    if (nx, ny) in mountains:
        adj += 1
        print(f"  Mountain: ({nx},{ny})")
    if p.get('feature') == 'FEATURE_GEOTHERMAL_FISSURE':
        adj += 1
        print(f"  Geothermal: ({nx},{ny})")
    if p.get('feature') == 'FEATURE_JUNGLE':
        print(f"  Jungle: ({nx},{ny})")

jungle_count = sum(1 for nx, ny in get_neighbors(21, 14) if plots.get((nx, ny), {}).get('feature') == 'FEATURE_JUNGLE')
print(f"  Jungle count: {jungle_count}, bonus: {jungle_count // 2}")
print(f"  Total base campus adj: {adj + jungle_count // 2}")

# Recheck with the function
def campus_base(x, y):
    adj = 0
    for nx, ny in get_neighbors(x, y):
        p = plots.get((nx, ny), {})
        if (nx, ny) in mountains:
            adj += 1
        if p.get('feature') == 'FEATURE_GEOTHERMAL_FISSURE':
            adj += 1
        if p.get('feature') == 'FEATURE_REEF':
            adj += 1
    jungle_count = sum(1 for nx, ny in get_neighbors(x, y) if plots.get((nx, ny), {}).get('feature') == 'FEATURE_JUNGLE')
    adj += jungle_count // 2
    return adj

print(f"\nCampus at (21,14) via function: {campus_base(21, 14)}")

# Hmm earlier said 4. Let me see...
# Actually maybe I had the wrong neighbor offsets before. Let me carefully check.
print("\n=== All Campus base adjacency values ===")
for (x, y) in sorted(buildable.keys(), key=lambda t: (t[1], t[0])):
    adj = campus_base(x, y)
    if adj > 0:
        neigh = get_neighbors(x, y)
        details = []
        for nx, ny in neigh:
            p = plots.get((nx, ny), {})
            if (nx, ny) in mountains:
                details.append(f"Mt({nx},{ny})")
            if p.get('feature') == 'FEATURE_GEOTHERMAL_FISSURE':
                details.append(f"Geo({nx},{ny})")
            if p.get('feature') == 'FEATURE_JUNGLE':
                details.append(f"Jgl({nx},{ny})")
            if p.get('feature') == 'FEATURE_REEF':
                details.append(f"Reef({nx},{ny})")
        print(f"  ({x},{y}): base={adj}  [{', '.join(details)}]")

