    rd1 = river_data.get((x1, y1), {})
    rd2 = river_data.get((x2, y2), {})
    if y1 % 2 == 0:
        if (dx,dy)==(1,0):  return rd2.get('IsWOfRiver', False)
        if (dx,dy)==(-1,0): return rd1.get('IsWOfRiver', False)
        if (dx,dy)==(0,1):  return rd1.get('IsNEOfRiver', False)
        if (dx,dy)==(-1,1): return rd1.get('IsNWOfRiver', False)
        if (dx,dy)==(0,-1): return rd2.get('IsNEOfRiver', False)
        if (dx,dy)==(-1,-1):return rd2.get('IsNWOfRiver', False)
