        if (dx,dy)==(-1,0): return rd1.get('IsWOfRiver', False)
        if (dx,dy)==(1,1):  return rd1.get('IsNEOfRiver', False)
        if (dx,dy)==(0,1):  return rd1.get('IsNWOfRiver', False)
        if (dx,dy)==(1,-1): return rd2.get('IsNEOfRiver', False)
