mountains = {(x,y) for (x,y),p in plots.items() if 'MOUNTAIN' in p['terrain']}

# Pre-compute river tiles
river_tile_set = set()
for pos in plots:
    if tile_has_river(*pos):
        river_tile_set.add(pos)

# Buildable tiles
buildable = {(x,y) for (x,y),p in plots.items() 
             if p['terrain'] not in ('TERRAIN_OCEAN','TERRAIN_COAST') and not p['impassable']}

def hex_distance(x1, y1, x2, y2):
