        cx = x - (y - (y & 1)) // 2
        cz = y
        cy = -cx - cz
        return cx, cy, cz
    c1 = to_cube(x1, y1)
    c2 = to_cube(x2, y2)
    return max(abs(c1[0]-c2[0]), abs(c1[1]-c2[1]), abs(c1[2]-c2[2]))

# ============================================================
# CORRECTED ADJACENCY WITH FEATURE REMOVAL
# ============================================================
# When a district (including city center and aqueduct) is placed on a tile,
# the feature on THAT tile is removed. Features on neighboring tiles that 
# don't have districts are preserved.

def compute_adjacency_correct(placements, city_center):
    """
    placements: dict of district_type -> (x,y)  (includes AQUEDUCT if any)
    city_center: (x,y)
    Returns dict of specialty_district_type -> adjacency_bonus

    Features are removed from tiles where districts are placed.
    """
    # Set of all tiles with a placement (city center + all districts)
    occupied = {city_center}
    for pos in placements.values():
        occupied.add(pos)

    all_placed = {city_center: 'CITY_CENTER'}
    for dtype, pos in placements.items():
        all_placed[pos] = dtype

    result = {}

    for dtype, pos in placements.items():
        if dtype == 'AQUEDUCT':
            continue  # Aqueduct doesn't get adjacency bonus

        base = 0
        minor_count = 0

        for nx, ny in neighbor_cache[pos]:
            nplot = plots.get((nx, ny), {})
            # Feature is present only if no district is placed on that tile
            has_feature = (nx, ny) not in occupied
            feature = nplot.get('feature') if has_feature else None

            placed_type = all_placed.get((nx, ny))

            # District-type-specific adjacency
            if dtype == 'CAMPUS':
                if (nx, ny) in mountains:
                    base += 1
                if feature == 'FEATURE_GEOTHERMAL_FISSURE':
                    base += 1
                if feature == 'FEATURE_REEF':
                    base += 1
                # Jungle counted below

            elif dtype == 'HOLY_SITE':
                if (nx, ny) in mountains:
                    base += 1
                # Forest counted below

            elif dtype == 'COMMERCIAL_HUB':
                pass  # River handled separately, harbor counted below

            elif dtype == 'INDUSTRIAL_ZONE':
                if placed_type == 'AQUEDUCT':
                    base += 2
                    # Don't count as minor district
                    continue

            elif dtype == 'THEATER_SQUARE':
                # +1 per adjacent entertainment complex/water park
                if placed_type in ('ENTERTAINMENT_COMPLEX', 'WATER_PARK'):
                    base += 1
                    # Don't count as minor for this specific interaction? 
                    # Actually in Civ6, these are MAJOR adjacency, not minor

            # District minor adjacency (+0.5 per adjacent district)
            if placed_type is not None:
                minor_count += 1

        # Handle special per-type counting
        if dtype == 'CAMPUS':
            # +1 per 2 adjacent jungle tiles (minor adjacency from jungles)
            jungle_count = 0
            for nx, ny in neighbor_cache[pos]:
                has_feature = (nx, ny) not in occupied
                feature = plots.get((nx, ny), {}).get('feature') if has_feature else None
                if feature == 'FEATURE_JUNGLE':
                    jungle_count += 1
            base += jungle_count // 2

        elif dtype == 'HOLY_SITE':
            # +1 per 2 adjacent forest tiles
            forest_count = 0
            for nx, ny in neighbor_cache[pos]:
                has_feature = (nx, ny) not in occupied
                feature = plots.get((nx, ny), {}).get('feature') if has_feature else None
                if feature == 'FEATURE_FOREST':
                    forest_count += 1
            base += forest_count // 2

        # Commercial Hub river bonus
        if dtype == 'COMMERCIAL_HUB':
            if pos in river_tile_set:
                base += 2

        # Minor district adjacency: floor(minor_count * 0.5) = minor_count // 2
        total = base + minor_count // 2
        result[dtype] = total

    return result

# ============================================================
# BRUTE FORCE OPTIMIZER (CORRECTED)
# ============================================================
# Population 9 -> 4 specialty district slots
# Available: CAMPUS, HOLY_SITE, COMMERCIAL_HUB, INDUSTRIAL_ZONE, THEATER_SQUARE
# Also: AQUEDUCT (free, not a slot) - must be adjacent to CC and mountain/river

NUM_DISTRICTS = 4

district_combos = [
    ['CAMPUS', 'COMMERCIAL_HUB', 'HOLY_SITE', 'INDUSTRIAL_ZONE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HOLY_SITE', 'THEATER_SQUARE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'THEATER_SQUARE'],
    ['CAMPUS', 'HOLY_SITE', 'INDUSTRIAL_ZONE', 'THEATER_SQUARE'],
    ['COMMERCIAL_HUB', 'HOLY_SITE', 'INDUSTRIAL_ZONE', 'THEATER_SQUARE'],
]

best_total = -1
best_solution = None
best_adj = None

# For each city center
for cc in sorted(buildable):
    # Get tiles within range 3
    visited = {cc}
    current = {cc}
    for r in range(3):
        next_ring = set()
        for pos in current:
            for n in neighbor_cache[pos]:
                if n not in visited:
                    next_ring.add(n)
                    visited.add(n)
        current = next_ring

    available = sorted(visited & buildable - {cc})

    if len(available) < 4:
        continue

    # Find potential aqueduct tiles (adjacent to CC, adjacent to mountain or river)
    aqueduct_candidates = []
    for at in available:
        if at not in set(neighbor_cache[cc]):
            continue
        adj_mountain = any((nx,ny) in mountains for nx, ny in neighbor_cache[at])
        adj_river = tile_has_river(*at)
        if adj_mountain or adj_river:
            aqueduct_candidates.append(at)

    for combo in district_combos:
        has_iz = 'INDUSTRIAL_ZONE' in combo

        # Determine candidate tiles for this combo
        # Include tiles that could contribute adjacency
        candidate_tiles = list(available)

        # For efficiency, limit to ~25 best candidates
        # Score each tile by max potential adjacency across district types
        def tile_score(t):
            s = 0
            for dtype in combo:
                if dtype == 'CAMPUS':
                    for nx, ny in neighbor_cache[t]:
                        if (nx,ny) in mountains: s += 1
                        feat = plots.get((nx,ny),{}).get('feature')
                        if feat == 'FEATURE_GEOTHERMAL_FISSURE': s += 1
                        if feat == 'FEATURE_REEF': s += 1
                        if feat == 'FEATURE_JUNGLE': s += 0.5
                elif dtype == 'HOLY_SITE':
                    for nx, ny in neighbor_cache[t]:
                        if (nx,ny) in mountains: s += 1
                        if plots.get((nx,ny),{}).get('feature') == 'FEATURE_FOREST': s += 0.5
                elif dtype == 'COMMERCIAL_HUB':
                    if t in river_tile_set: s += 2
                elif dtype == 'INDUSTRIAL_ZONE':
                    pass
            # Clustering bonus: being adjacent to other candidate tiles
            adj_buildable = sum(1 for n in neighbor_cache[t] if n in buildable and n != cc)
            s += adj_buildable * 0.3
            return s

        candidate_tiles.sort(key=tile_score, reverse=True)
        candidate_tiles = candidate_tiles[:22]

        # Try all permutations of 4 tiles from candidates
        for perm in permutations(candidate_tiles, 4):
            placements = dict(zip(combo, perm))
            adj = compute_adjacency_correct(placements, cc)
            total = sum(adj.values())

            if total > best_total:
                best_total = total
                best_solution = {'cc': cc, 'placements': dict(placements), 'aqueduct': None}
                best_adj = dict(adj)

        # Try with aqueduct if IZ in combo
        if has_iz:
            for aq in aqueduct_candidates:
                remaining = [t for t in candidate_tiles if t != aq]
                for perm in permutations(remaining, 4):
                    if aq in perm:
                        continue
                    placements = dict(zip(combo, perm))
                    placements['AQUEDUCT'] = aq
                    adj = compute_adjacency_correct(placements, cc)
                    total = sum(adj.values())

                    if total > best_total:
                        best_total = total
                        best_solution = {'cc': cc, 'placements': dict(placements), 'aqueduct': aq}
                        best_adj = dict(adj)

print(f"Best total adjacency: {best_total}")
print(f"City center: {best_solution['cc']}")
print(f"Placements: {best_solution['placements']}")
print(f"Adjacency: {best_adj}")
print(f"Aqueduct: {best_solution['aqueduct']}")

